{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "request" : {
      "type" : "object",
      "properties" : {
        "dimensions" : {
          "description" : "分组维度名列表（取自 listSemanticCatalog），如 [\"STORE_CODE\"]；最多 5 个",
          "type" : "array",
          "items" : {
            "type" : "string",
            "description" : "分组维度名列表（取自 listSemanticCatalog），如 [\"STORE_CODE\"]；最多 5 个"
          }
        },
        "entities" : {
          "description" : "实体列表，首个为主表；跨实体组合需在元数据声明关系，如 [\"order\",\"member\"]",
          "type" : "array",
          "items" : {
            "type" : "string",
            "description" : "实体列表，首个为主表；跨实体组合需在元数据声明关系，如 [\"order\",\"member\"]"
          }
        },
        "filters" : {
          "description" : "过滤条件（可选）：preset 引用条件模板 ID，或 column+op+value 结构化直传",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "column" : {
                "type" : "string",
                "description" : "结构化过滤列（白名单内）"
              },
              "entity" : {
                "type" : "string",
                "description" : "过滤列所属实体，缺省为 entities[0]"
              },
              "op" : {
                "type" : "string",
                "description" : "操作符：= != > < >= <= LIKE IN NOT IN IS NULL IS NOT NULL"
              },
              "preset" : {
                "type" : "string",
                "description" : "引用条件模板 ID（与 column 二选一）"
              },
              "value" : {
                "type" : "string",
                "description" : "单值过滤值，等值/比较/LIKE 参数化传入；IN/NOT IN 与 IS NULL 类不需要"
              },
              "values" : {
                "description" : "IN/NOT IN 的多值列表，去重后最多 500 个；仅 op=IN/NOT IN 时填写，value 必须留空；值含逗号也按一个完整值处理，不要拆分",
                "type" : "array",
                "items" : {
                  "type" : "string",
                  "description" : "IN/NOT IN 的多值列表，去重后最多 500 个；仅 op=IN/NOT IN 时填写，value 必须留空；值含逗号也按一个完整值处理，不要拆分"
                }
              }
            },
            "description" : "过滤条件（可选）：preset 引用条件模板 ID，或 column+op+value 结构化直传"
          }
        },
        "limit" : {
          "type" : "integer",
          "format" : "int32",
          "description" : "返回行数，默认 100（实体守卫可覆盖缺省，如 detail=500），上限 1000"
        },
        "measures" : {
          "description" : "度量列表：type=simple|conditional|distinct|derived；simple/conditional/distinct 用 name 引用元数据度量，derived 用 formula 引用本请求已声明 alias",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "alias" : {
                "type" : "string",
                "description" : "输出 alias：^[a-z][a-z0-9_]{0,31}$，同请求内唯一"
              },
              "conditionPreset" : {
                "type" : "string",
                "description" : "type=conditional 时引用条件模板 ID，如 IS_VIP"
              },
              "formula" : {
                "type" : "string",
                "description" : "type=derived 时的公式，仅支持 + - * / 括号与本请求已声明 alias"
              },
              "name" : {
                "type" : "string",
                "description" : "引用元数据声明的度量名（type=derived 时不用）"
              },
              "scale" : {
                "type" : "integer",
                "format" : "int32",
                "description" : "type=derived 的小数位，默认 2"
              },
              "type" : {
                "type" : "string",
                "description" : "类型：simple|conditional|distinct|derived"
              }
            },
            "required" : [ "alias", "type" ],
            "description" : "度量列表：type=simple|conditional|distinct|derived；simple/conditional/distinct 用 name 引用元数据度量，derived 用 formula 引用本请求已声明 alias"
          }
        },
        "orderBy" : {
          "type" : "string",
          "description" : "排序，形如 \"SALES desc\"；只能引用本请求输出的维度/度量 alias"
        },
        "timeRange" : {
          "type" : "object",
          "properties" : {
            "endDate" : {
              "type" : "string",
              "description" : "结束日期 yyyy-MM-dd（含当日，即右开 +1 天）"
            },
            "entity" : {
              "type" : "string",
              "description" : "时间列所属实体，缺省为 entities[0]"
            },
            "startDate" : {
              "type" : "string",
              "description" : "开始日期 yyyy-MM-dd（含）"
            },
            "timeDimension" : {
              "type" : "string",
              "description" : "时间维度名（元数据 timeColumns 的 key），如 TRACK_TIME"
            }
          },
          "required" : [ "endDate", "startDate", "timeDimension" ],
          "description" : "时间窗口（可选）：引用实体声明的 timeDimension，左闭右开含结束日全天"
        }
      },
      "required" : [ "dimensions", "entities", "measures" ]
    }
  },
  "required" : [ "request" ],
  "additionalProperties" : false
}

