{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "request" : {
      "type" : "object",
      "properties" : {
        "attributes" : {
          "description" : "非聚合描述列列表，可选；每项 {column,alias,agg}，默认 MAX",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "agg" : {
                "type" : "string",
                "description" : "聚合函数，可选；SUM|COUNT|MAX|MIN|AVG，默认 MAX"
              },
              "alias" : {
                "type" : "string",
                "description" : "输出别名（如 station_name）"
              },
              "column" : {
                "type" : "string",
                "description" : "描述列（如 expense_stationName），建议 join 指标带限定符"
              }
            },
            "required" : [ "alias", "column" ],
            "description" : "非聚合描述列列表，可选；每项 {column,alias,agg}，默认 MAX"
          }
        },
        "baselineFilters" : {
          "description" : "恒定 WHERE 字面量片段列表，可选；只允许字面量，禁止占位符/写操作/注释（含 del_flag 等同名列时 join 指标须带限定符）",
          "type" : "array",
          "items" : {
            "type" : "string",
            "description" : "恒定 WHERE 字面量片段列表，可选；只允许字面量，禁止占位符/写操作/注释（含 del_flag 等同名列时 join 指标须带限定符）"
          }
        },
        "caliber" : {
          "type" : "string",
          "description" : "口径正文，必填；必须由人工/产品提供（状态位、退单处理、时间边界、统计粒度）。脚手架不猜口径"
        },
        "defaultSortBy" : {
          "type" : "string",
          "description" : "默认排序度量编码，可选；必须在 sortable 内"
        },
        "defaultSortDir" : {
          "type" : "string",
          "description" : "默认排序方向 asc|desc，可选；默认 desc"
        },
        "defaultWindowMonths" : {
          "type" : "integer",
          "format" : "int32",
          "description" : "指标级缺省时间窗口（月），可选；0=沿用看板默认（近一年半）"
        },
        "derived" : {
          "description" : "派生指标列表，可选；每项 {code,formula,scale,unit}，Java 端四则计算，不进 SQL",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "code" : {
                "type" : "string",
                "description" : "派生编码，UPPER_SNAKE，如 AVG_ORDER_VALUE"
              },
              "formula" : {
                "type" : "string",
                "description" : "四则运算公式，操作数为 measure/derived 编码，如 SALES / ORDERS"
              },
              "scale" : {
                "type" : "integer",
                "format" : "int32",
                "description" : "结果小数位，可选；默认 2"
              },
              "unit" : {
                "type" : "string",
                "description" : "单位，可选"
              }
            },
            "required" : [ "code", "formula" ],
            "description" : "派生指标列表，可选；每项 {code,formula,scale,unit}，Java 端四则计算，不进 SQL"
          }
        },
        "dimensions" : {
          "description" : "分组维度列表，可选；每项 {code,column/expr,alias}。留空=只做全局聚合",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "alias" : {
                "type" : "string",
                "description" : "SQL 列别名，可选；留空默认取 code 小写"
              },
              "code" : {
                "type" : "string",
                "description" : "维度编码，UPPER_SNAKE，如 STATION/GENDER"
              },
              "column" : {
                "type" : "string",
                "description" : "简单列引用（如 expense_stationCode 或 join 指标下的 e.expense_stationCode）"
              },
              "expr" : {
                "type" : "string",
                "description" : "复杂分组表达式（如 CASE WHEN ... END），与 column 二选一，优先取 expr"
              }
            },
            "required" : [ "code" ],
            "description" : "分组维度列表，可选；每项 {code,column/expr,alias}。留空=只做全局聚合"
          }
        },
        "domain" : {
          "type" : "string",
          "description" : "业务域，必填；member|order|delivery|finance 之一"
        },
        "grain" : {
          "type" : "string",
          "description" : "统计粒度，可选；ORDER_HEAD|ORDER_DETAIL|MEMBER|CONFIG。留空时按主表推断（表→粒度是已验证的硬映射，非业务猜测）"
        },
        "join" : {
          "type" : "object",
          "properties" : {
            "joinAlias" : {
              "type" : "string",
              "description" : "关联表别名（如 m），不得与主表/关联表同名"
            },
            "joinTable" : {
              "type" : "string",
              "description" : "关联表，必须在表白名单内（如 member_info）"
            },
            "mainAlias" : {
              "type" : "string",
              "description" : "主表别名（如 e）；声明 join 后所有列引用须带 mainAlias./joinAlias. 限定符"
            },
            "onLeftCol" : {
              "type" : "string",
              "description" : "关联键：主表列（裸列或已带 mainAlias 限定均可，如 expense_mobile）"
            },
            "onRightCol" : {
              "type" : "string",
              "description" : "关联键：关联表列（裸列或已带 joinAlias 限定均可，如 member_mobile）；PII 关联键须已在 piiComputeAllowedColumns"
            }
          },
          "required" : [ "joinAlias", "joinTable", "mainAlias", "onLeftCol", "onRightCol" ],
          "description" : "受控 1:1 关联（路线 C），可选；声明后列引用须自行带限定符，ON 由脚手架按主表/关联别名组装"
        },
        "limitDefault" : {
          "type" : "integer",
          "format" : "int32",
          "description" : "默认返回条数，可选；默认 100"
        },
        "limitMax" : {
          "type" : "integer",
          "format" : "int32",
          "description" : "最大返回条数，可选；默认 500，不得超过全局硬上限 2000"
        },
        "maxRangeDays" : {
          "type" : "integer",
          "format" : "int32",
          "description" : "指标级时间跨度上限（天），可选；0=沿用全局上限，适用于窗口一大就超时的明细表指标"
        },
        "measures" : {
          "description" : "度量（聚合表达式）列表，必填且至少一个；每项 {code,agg,column/expr,alias,unit,decimalScale,zeroFill}。VARCHAR 金额列命中登记表时自动包 NUM()",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "agg" : {
                "type" : "string",
                "description" : "聚合函数：SUM|COUNT|MAX|MIN|AVG"
              },
              "alias" : {
                "type" : "string",
                "description" : "SQL 列别名，可选；留空默认取 code 小写"
              },
              "code" : {
                "type" : "string",
                "description" : "度量编码，UPPER_SNAKE，如 SALES/ORDERS"
              },
              "column" : {
                "type" : "string",
                "description" : "聚合对象列；VARCHAR 金额/数量命中登记表时自动包 NUM()。COUNT 行数可留空或传 *"
              },
              "decimalScale" : {
                "type" : "integer",
                "format" : "int32",
                "description" : "小数位，可选；默认 2，用于 NUM() 展开的 DECIMAL(20,scale)"
              },
              "expr" : {
                "type" : "string",
                "description" : "完整聚合对象表达式（如 DISTINCT e.expense_mobile），与 column 二选一，优先取 expr"
              },
              "unit" : {
                "type" : "string",
                "description" : "单位，可选；CNY|COUNT|PCS|PERCENT 等，供模型正确表述"
              },
              "zeroFill" : {
                "type" : "boolean",
                "description" : "是否兜零（COALESCE(...,0)），可选；默认 false"
              }
            },
            "required" : [ "agg", "code" ],
            "description" : "度量（聚合表达式）列表，必填且至少一个；每项 {code,agg,column/expr,alias,unit,decimalScale,zeroFill}。VARCHAR 金额列命中登记表时自动包 NUM()"
          }
        },
        "metric" : {
          "type" : "string",
          "description" : "指标编码，必填；UPPER_SNAKE，如 STATION_SALES；须全局唯一（与现有指标重名会在返回里报错）"
        },
        "nullDimensionLabel" : {
          "type" : "string",
          "description" : "空/缺失维度归并展示名，可选；如\"未知门店\"。声明了它却没有任何维度会被判可疑"
        },
        "optionalFilters" : {
          "description" : "可选过滤列表，可选；每项 {code,column}，命中请求时生成 column = ? 参数化条件",
          "type" : "array",
          "items" : {
            "type" : "object",
            "properties" : {
              "code" : {
                "type" : "string",
                "description" : "过滤编码，UPPER_SNAKE，如 STATION/SKU"
              },
              "column" : {
                "type" : "string",
                "description" : "过滤列，建议 join 指标带限定符；不得是 PII 列"
              }
            },
            "required" : [ "code", "column" ],
            "description" : "可选过滤列表，可选；每项 {code,column}，命中请求时生成 column = ? 参数化条件"
          }
        },
        "sortable" : {
          "description" : "允许排序的度量编码白名单，可选；留空时默认取全部度量编码",
          "type" : "array",
          "items" : {
            "type" : "string",
            "description" : "允许排序的度量编码白名单，可选；留空时默认取全部度量编码"
          }
        },
        "status" : {
          "type" : "string",
          "description" : "口径状态，可选；缺省一律 UNCONFIRMED（防起草即\"看起来权威\"）。仅当业务已确认才显式传 CONFIRMED"
        },
        "table" : {
          "type" : "string",
          "description" : "主表，必填；必须在列类型登记表（表白名单）内"
        },
